EQUITY={'verified_arithmetic': True, 'visual_pending': False, 'source': '1225642095', 'physical_page': 9, 'parent_equity_yuan': '-283932486.67', 'minority_equity_yuan': '-43460791.17', 'total_equity_yuan': '-327393277.84', 'later_notice': '1225662730', 'later_notice_page': 1, 'interpretation': '归母权益与合并所有者权益不是同一指标；相加与后续公告净资产完全一致，保留口径，不擅自改源。', 'visual_reviewed_pages': [2, 9]}
def followup_view(inputs, prior):
    packet=inputs.get('eighteenth_period_followup')
    if packet is None:return None
    if packet['version']!=1 or packet['content_digest']!=digest({k:v for k,v in packet.items()if k!='content_digest'}):raise ValueError('eighteenth period packet changed')
    if prior is None or prior['counts']['after']!=114 or packet['prior_digest']!=digest(prior):raise ValueError('eighteenth period prior changed')
    market=inputs['current_extension']['market_inputs']
    if packet['market_digest']!=digest(market):raise ValueError('eighteenth period market changed')
    sources={s['announcement_id']:s for s in packet['sources']}
    if len(sources)!=29 or len(packet['sources'])!=29 or set(sources)!=set(SOURCE_BINDINGS):raise ValueError('eighteenth period source set changed')
    if packet['visual_read']!=VISUAL:raise ValueError('eighteenth period visual scope changed')
    for aid,s in sources.items():
        if {k:s.get(k)for k in SOURCE_BINDINGS[aid]}!=SOURCE_BINDINGS[aid]or not s['protected_gate_passed']:raise ValueError('eighteenth period source binding changed')
        if s['published_on']>'2026-11-19':raise ValueError('eighteenth period future source')
        if set(s['selected_pages'])!={str(n)for n in range(1,s['pages']+1)}or len(s['page_hashes'])!=s['pages']:raise ValueError('eighteenth period pages missing')
        for n,t in s['selected_pages'].items():
            if sha256(t.encode()).hexdigest()!=s['page_hashes'][int(n)-1]:raise ValueError('eighteenth period page changed')
    for row in FINANCIAL:
        h,old,nine=D(row['h1_yuan']),D(row['prior_h1_yuan']),D(row['nine_month_yuan'])
        yoy=((h-old)/abs(old)*100).quantize(D('.01'),rounding=ROUND_HALF_UP)
        if yoy!=D(row['h1_yoy_pct']):raise ValueError('eighteenth period H1 arithmetic changed')
        if row['reported_h1_yoy_pct']is not None and yoy!=D(row['reported_h1_yoy_pct']):raise ValueError('eighteenth period reported H1 changed')
        if nine-h!=D(row['quarter_yuan']):raise ValueError('eighteenth period quarter changed')
        if row['reported_quarter_yuan']is not None:
            delta=nine-h-D(row['reported_quarter_yuan'])
            if delta!=D(row['quarter_difference_yuan']):raise ValueError('eighteenth period preserved quarter difference changed')
            expected='direct_and_difference_checked'if delta==0 else 'reported_and_difference_conflict'
            if row['quarter_basis']!=expected:raise ValueError('eighteenth period quarter label changed')
        elif row['quarter_basis']!='nine_month_minus_h1':raise ValueError('eighteenth period derived quarter label changed')
        for aid,n,keys in [(row['h1_source'],row['h1_page'],['h1_yuan','prior_h1_yuan']),(row['q3_source'],row['q3_page'],['nine_month_yuan']+(['reported_quarter_yuan']if row['reported_quarter_yuan']is not None else []))]:
            text=sources[aid]['selected_pages'][str(n)].replace(',','').replace('\n','').replace(' ','')
            if any(row[k]not in text for k in keys):raise ValueError('eighteenth period financial source changed')
    from st_regime_comparison import build
    windows=event_windows(market,build(market)['daily'],list(sources.values()),allow_nontraded=True,allow_missing=True)
    if digest(windows)!=packet['event_windows_digest']:raise ValueError('eighteenth period windows changed')
    if any(r['quarter_basis']=='reported_and_difference_conflict'for r in FINANCIAL):raise ValueError('eighteenth period unexpected financial conflict')
    result={'through': '2026-11-19', 'title': '正式摘帽、处罚与协议调整，怎样更新判断？', 'answer': '长园已正式撤销警示，后续季度经营和分案诉讼仍须独立看；湘邮财政部处罚不等于证监会调查结束。亿晶调整的是产业投资人出资与未来控制权安排，正式受理和实际投资到账仍待核；柳化盈利改善，全年审核条件继续保留。', 'counts': {'files': 29, 'new_files': 29, 'reused_files': 0, 'pages': 886, 'new_pages': 886, 'viewed_pages': 27, 'initial_coverage': 114, 'complete_windows': 75, 'unfinished_windows': 12, 'stock_endpoint_gaps': 1}, 'boundary': '125条目录，29份886页中核27关键视觉页，不称全文或催化穷尽。87公告窗口75满12未满，1股票缺价保留，86可算股票窗口和85端点核；36阶段40端点不重复计验证。16财务12单季直接相符4现金差额，湘邮/长园采用调整后基期并保留原表标记。长园撤销前上涨与生效区间回落并列；总股东权益/归母权益、公司/个人罚款、终审/未生效一审/上诉分别核。旧专题更正与缺口保留，不晋级经验。', 'method_promotions': 0}
    result.update(chains=CHAINS,financial_bridge=FINANCIAL,phase_comparisons=PHASES,equity_basis=EQUITY,event_windows=windows,sources=[{k:v for k,v in s.items()if k not in ['raw_item','selected_pages','page_hashes']}for s in sources.values()])
    return result
